57: /// Decoded Gimbal Telemetry Record (Record Type 3).
58: #[derive(Debug, Clone, PartialEq)]
59: pub struct GimbalRecord {
60:     /// Raw signed pitch angle (deci-degrees, $\times 10$).
61:     pub raw_pitch: i16,
62:     /// Raw signed roll angle (deci-degrees, $\times 10$).
63:     pub raw_roll: i16,
64:     /// Raw signed yaw angle (deci-degrees, $\times 10$).
65:     pub raw_yaw: i16,
66:     /// Raw status and limit bitmask byte.
67:     pub raw_bitmask: u8,
68:     /// Raw signed tilt angle relative to horizon (deci-degrees, $\times 10$), if available.
69:     pub raw_tilt: Option<i16>,
70: 
71:     /// Gimbal pitch angle in decimal degrees ($-90.0^\circ \dots +30.0^\circ$).
72:     /// Positive values tilt upward; negative values tilt downward toward nadir.
73:     pub pitch_deg: f64,
74:     /// Gimbal roll leveling angle in decimal degrees.
75:     pub roll_deg: f64,
76:     /// Gimbal yaw azimuth angle in decimal degrees ($-180.0^\circ \dots +180.0^\circ$ relative to nose).
77:     pub yaw_deg: f64,
78:     /// Absolute gimbal tilt angle relative to horizon in decimal degrees, if present.
79:     pub tilt_deg: Option<f64>,
80: 
