93: impl GimbalRecord {
94:     /// Parses a Gimbal telemetry record from a borrowed payload slice.
95:     ///
96:     /// # Errors
97:     /// Returns [`FlightReaderError::TruncatedRecord`] if `payload.len() < 7`.
98:     pub fn parse(payload: &[u8]) -> Result<Self> {
99:         if payload.len() < MIN_PAYLOAD_LEN {
100:             return Err(FlightReaderError::TruncatedRecord {
101:                 expected: MIN_PAYLOAD_LEN,
102:                 available: payload.len(),
103:             });
104:         }
105: 
106:         let raw_pitch = LittleEndian::read_i16(&payload[0..2]);
107:         let raw_roll = LittleEndian::read_i16(&payload[2..4]);
108:         let raw_yaw = LittleEndian::read_i16(&payload[4..6]);
109:         let raw_bitmask = payload[6];
110: 
111:         let (raw_tilt, tilt_deg) = if payload.len() >= EXTENDED_PAYLOAD_LEN {
112:             let t = LittleEndian::read_i16(&payload[20..22]);
113:             (Some(t), Some(t as f64 / 10.0))
114:         } else {
115:             (None, None)
116:         };
117: 
118:         let pitch_deg = raw_pitch as f64 / 10.0;
119:         let roll_deg = raw_roll as f64 / 10.0;
120:         let yaw_deg = raw_yaw as f64 / 10.0;
121: 
122:         let is_at_pitch_limit = (raw_bitmask & 0x01) != 0;
123:         let is_at_roll_limit = (raw_bitmask & 0x02) != 0;
124:         let is_at_yaw_limit = (raw_bitmask & 0x04) != 0;
125:         let is_stuck = (raw_bitmask & 0x40) != 0;
126:         let mode = GimbalMode::from_bits((raw_bitmask >> 6) & 0x03);
127: 
128:         Ok(Self {
129:             raw_pitch,
130:             raw_roll,
131:             raw_yaw,
132:             raw_bitmask,
133:             raw_tilt,
134:             pitch_deg,
135:             roll_deg,
136:             yaw_deg,
137:             tilt_deg,
138:             is_at_pitch_limit,
139:             is_at_roll_limit,
140:             is_at_yaw_limit,
141:             is_stuck,
142:             mode,
143:         })
144:     }
145: 
146:     /// Normalizes yaw azimuth to the standard compass interval $[0.0^\circ, 360.0^\circ)$.
147:     #[inline]
148:     pub fn yaw_360(&self) -> f64 {
149:         if self.yaw_deg < 0.0 {
150:             self.yaw_deg + 360.0
151:         } else {
152:             self.yaw_deg
153:         }
154:     }
155: 
156:     /// Returns `true` if any mechanical or configured axis limit is hit.
157:     #[inline]
158:     pub const fn is_at_any_limit(&self) -> bool {
159:         self.is_at_pitch_limit || self.is_at_roll_limit || self.is_at_yaw_limit
160:     }
161: }
