1: //! DJI `.txt` Remote Controller Telemetry Decoder (Record Type 4).
2: //!
3: //! Decodes 4 physical control stick axes (Aileron, Elevator, Throttle, Rudder),
4: //! gimbal pitch dial (Gyro), flight mode switches, wheel scroll, and button bitmasks.
5: 
6: use byteorder::{ByteOrder, LittleEndian};
7: 
8: use crate::error::{FlightReaderError, Result};
