10: /// Telemetry record type identifier for Remote Controller packets.
11: pub const RECORD_TYPE: u8 = 4;
12: 
13: /// Minimum allowable payload length (bytes 0..9: sticks + gyro).
14: pub const MIN_PAYLOAD_LEN: usize = 10;
15: 
16: /// Standard payload length including 32-bit button/switch bitmask.
17: pub const STANDARD_PAYLOAD_LEN: usize = 14;
18: 
19: /// Calibrated stick center / neutral value.
20: pub const STICK_CENTER: i16 = 1024;
21: 
22: /// Calibrated stick minimum travel boundary.
23: pub const STICK_MIN: i16 = 364;
24: 
25: /// Calibrated stick maximum travel boundary.
26: pub const STICK_MAX: i16 = 1684;
27: 
28: /// Calibrated half-span range $(1684 - 1024 = 660.0)$.
29: pub const STICK_HALF_RANGE: f64 = 660.0;
30: 
31: /// Normalizes a raw 16-bit stick channel into a floating point value in `[-1.0, +1.0]`.
32: ///
33: /// Disconnected / uninitialized channels (`raw == 0`) map to neutral center `1024` (`0.0`).
34: /// Values beyond `[364, 1684]` are linearly extrapolated beyond `[-1.0, +1.0]`.
35: #[inline]
36: pub fn normalize_stick(raw: i16) -> f64 {
37:     let effective = if raw == 0 {
38:         STICK_CENTER as f64
39:     } else {
40:         raw as f64
41:     };
42:     (effective - STICK_CENTER as f64) / STICK_HALF_RANGE
43: }
44: 
45: /// Clamps the normalized stick value to the valid operational range `[-1.0, +1.0]`.
46: #[inline]
47: pub fn normalize_stick_clamped(raw: i16) -> f64 {
48:     normalize_stick(raw).clamp(-1.0, 1.0)
49: }
50: 
51: /// Converts a raw 16-bit stick value into an integer percentage in `[-100, +100]`.
52: #[inline]
53: pub fn stick_percent(raw: i16) -> i8 {
54:     let norm = normalize_stick(raw);
55:     (norm * 100.0).round() as i8
56: }
57: 
58: /// Returns whether the stick channel is at or beyond physical endpoint saturation.
59: #[inline]
60: pub fn is_stick_saturated(raw: i16) -> bool {
61:     raw != 0 && (raw <= STICK_MIN || raw >= STICK_MAX)
62: }
