157: impl RcRecord {
158:     /// Parses an RC telemetry record from a borrowed payload slice.
159:     ///
160:     /// # Errors
161:     /// Returns [`FlightReaderError::TruncatedRecord`] if `payload.len() < 10`.
162:     pub fn parse(payload: &[u8]) -> Result<Self> {
163:         if payload.len() < MIN_PAYLOAD_LEN {
164:             return Err(FlightReaderError::TruncatedRecord {
165:                 expected: MIN_PAYLOAD_LEN,
166:                 available: payload.len(),
167:             });
168:         }
169: 
170:         let raw_aileron = LittleEndian::read_i16(&payload[0..2]);
171:         let raw_elevator = LittleEndian::read_i16(&payload[2..4]);
172:         let raw_throttle = LittleEndian::read_i16(&payload[4..6]);
173:         let raw_rudder = LittleEndian::read_i16(&payload[6..8]);
174:         let raw_gyro = LittleEndian::read_i16(&payload[8..10]);
175: 
176:         // Resilient variable-length bitmask extraction (10 to 14+ bytes)
177:         let raw_button_bitmask = if payload.len() >= 14 {
178:             LittleEndian::read_u32(&payload[10..14])
179:         } else if payload.len() == 13 {
180:             (payload[10] as u32) | ((payload[11] as u32) << 8) | ((payload[12] as u32) << 16)
181:         } else if payload.len() == 12 {
182:             (payload[10] as u32) | ((payload[11] as u32) << 8)
183:         } else if payload.len() == 11 {
184:             payload[10] as u32
185:         } else {
186:             0u32
187:         };
188: 
189:         let aileron = normalize_stick(raw_aileron);
190:         let elevator = normalize_stick(raw_elevator);
191:         let throttle = normalize_stick(raw_throttle);
192:         let rudder = normalize_stick(raw_rudder);
193:         let gyro = normalize_stick(raw_gyro);
194: 
195:         let wheel_depressed = (raw_button_bitmask & 0x01) != 0;
196:         let wheel_offset = ((raw_button_bitmask >> 1) & 0x1F) as u8;
197:         let signal_quality = (raw_button_bitmask & 0x7F) as u8;
198:         let go_home_depressed = (raw_button_bitmask & (1 << 11)) != 0;
199:         let mode_raw = ((raw_button_bitmask >> 12) & 0x03) as u8;
200:         let mode_switch = RcSwitchMode::from_bits(mode_raw);
201:         let custom4_depressed = (raw_button_bitmask & (1 << 17)) != 0;
202:         let custom3_depressed = (raw_button_bitmask & (1 << 18)) != 0;
203:         let custom2_depressed = (raw_button_bitmask & (1 << 19)) != 0;
204:         let custom1_depressed = (raw_button_bitmask & (1 << 20)) != 0;
205:         let playback_depressed = (raw_button_bitmask & (1 << 21)) != 0;
206:         let shutter_depressed = (raw_button_bitmask & (1 << 22)) != 0;
207:         let record_depressed = (raw_button_bitmask & (1 << 23)) != 0;
208: 
209:         Ok(Self {
210:             raw_aileron,
211:             raw_elevator,
212:             raw_throttle,
213:             raw_rudder,
214:             raw_gyro,
215:             raw_button_bitmask,
216:             aileron,
217:             elevator,
218:             throttle,
219:             rudder,
220:             gyro,
221:             wheel_depressed,
222:             wheel_offset,
223:             signal_quality,
224:             go_home_depressed,
225:             mode_raw,
226:             mode_switch,
227:             custom4_depressed,
228:             custom3_depressed,
229:             custom2_depressed,
230:             custom1_depressed,
231:             playback_depressed,
232:             shutter_depressed,
233:             record_depressed,
234:         })
235:     }
