238:     #[inline]
239:     pub fn aileron_percent(&self) -> i8 {
240:         stick_percent(self.raw_aileron)
241:     }
242: 
243:     /// Elevator deflection percentage in `[-100, +100]`.
244:     #[inline]
245:     pub fn elevator_percent(&self) -> i8 {
