261:     /// Returns `true` if all 4 flight control sticks are centered at neutral `1024` (or `0`).
262:     #[inline]
263:     pub fn is_neutral(&self) -> bool {
264:         (self.raw_aileron == STICK_CENTER || self.raw_aileron == 0)
265:             && (self.raw_elevator == STICK_CENTER || self.raw_elevator == 0)
266:             && (self.raw_throttle == STICK_CENTER || self.raw_throttle == 0)
267:             && (self.raw_rudder == STICK_CENTER || self.raw_rudder == 0)
268:     }
