270:     /// Returns `true` if any customizable button (C1, C2, C3, C4) is pressed.
271:     #[inline]
272:     pub const fn any_custom_button_pressed(&self) -> bool {
273:         self.custom1_depressed
274:             || self.custom2_depressed
275:             || self.custom3_depressed
276:             || self.custom4_depressed
277:     }
