303: fn test_rc_full_deflection_and_switches() {
304:     let mut payload = vec![0u8; RC_STANDARD_PAYLOAD_LEN];
305:     LittleEndian::write_i16(&mut payload[0..2], STICK_MAX); // Aileron: +1.0
306:     LittleEndian::write_i16(&mut payload[2..4], STICK_MIN); // Elevator: -1.0
307:     LittleEndian::write_i16(&mut payload[4..6], STICK_MAX); // Throttle: +1.0
308:     LittleEndian::write_i16(&mut payload[6..8], STICK_MIN); // Rudder: -1.0
309:     LittleEndian::write_i16(&mut payload[8..10], 1354); // Gyro: +0.5
310: 
311:     // Bitmask construction:
312:     // Bit 0: wheel_depressed = 1
313:     // Bits 1..5: wheel_offset = 10 -> (10 << 1) = 20
314:     // Bit 11: go_home_depressed = 1 -> (1 << 11) = 0x0800
315:     // Bits 12..13: mode_raw = 1 (Sport) -> (1 << 12) = 0x1000
316:     // Bit 20: custom1_depressed = 1 -> (1 << 20) = 0x0010_0000
317:     // Bit 22: shutter_depressed = 1 -> (1 << 22) = 0x0040_0000
318:     // Bit 23: record_depressed = 1 -> (1 << 23) = 0x0080_0000
319:     let bitmask: u32 = 1 | 20 | 0x0800 | 0x1000 | 0x0010_0000 | 0x0040_0000 | 0x0080_0000;
320:     LittleEndian::write_u32(&mut payload[10..14], bitmask);
321: 
322:     let rc = RcRecord::parse(&payload).expect("Must parse deflected RC record");
323:     assert!((rc.aileron - 1.0).abs() < 1e-9);
324:     assert!((rc.elevator - (-1.0)).abs() < 1e-9);
325:     assert!((rc.throttle - 1.0).abs() < 1e-9);
326:     assert!((rc.rudder - (-1.0)).abs() < 1e-9);
